const $=s=>document.querySelector(s);let symbols=['BTC','ETH','SOL','BNB','XRP','DOGE','AVAX','LINK','ADA','DOT','NEAR','SUI','LTC','BCH','APT','ARB','OP','INJ','ATOM','FIL','ETC','UNI','AAVE','TRX','TON','WIF','PEPE','SHIB','SEI','TIA','RUNE','FET','TAO','ONDO','JUP','WLD','ENA','PENDLE','CRV','LDO','DYDX','SAND','GALA','POL','IMX','RENDER','BONK','PYTH','JTO','STX','ICP','HBAR','ALGO','VET','XLM','EOS','ZEC','NEO','XTZ','QNT'];
let markets=new Map(),filter='all',savedOnly=false,demo=false,generation=0,socket=null,tf=1,rangeKey='15m',selected=null,lastTick=0,scanBusy=false,tradeDelta=0,book=null,detailSocket=null,detailUpdated=0;
let liquidations={long:0,short:0,start:null,connected:false};let proChart=null;let forecastHorizon=7;let saved=new Set();
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const price=n=>Number.isFinite(+n)?(+n).toLocaleString('en-US',{maximumFractionDigits:+n<1?6:+n<100?4:2}):'—';
const compact=n=>Number.isFinite(+n)?Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:2}).format(+n):'—';
const pct=n=>(n>=0?'+':'')+(+n).toFixed(2)+'%';
const fresh=()=>demo||lastTick&&Date.now()-lastTick<30000;
function spark(c,w=160,h=26){const v=c.map(x=>x.c),min=Math.min(...v),max=Math.max(...v),range=max-min||1;return v.map((x,i)=>`${i/(v.length-1)*w},${h-3-(x-min)/range*(h-6)}`).join(' ');}
function status(m){if(!fresh())return 'Stale';if(!demo&&m.a&&Date.now()-(m.a.last.t+tf*60000)>tf*60000)return 'Stale';if(!demo&&m.a){const q=dataQuality(m,{minutes:tf});if(q.gaps||q.candleCount<30)return 'Insufficient data';}return m.a?.status??'Loading';}
let pendingRender=false;function scheduleRender(){if(pendingRender)return;pendingRender=true;setTimeout(()=>{pendingRender=false;render();if(selected&&$('#detail').open)renderDetail();},700);}
function flowMarkup(m,large=false){const f=m.flow?.summary();if(!f?.total)return `<div class="flowEmpty">Buy / sell volume · waiting for trades</div>`;const stale=!demo&&(!fresh()||Date.now()-f.newest>30000);return `<div class="flow ${large?'flowLarge':''} ${stale?'flowStale':''}" title="Taker-side traded volume, not unique traders. Latest up to 1,000 observed trades within five minutes."><div class="flowLabels"><span class="green">Buy ${f.buyPct.toFixed(1)}%</span><span class="red">Sell ${f.sellPct.toFixed(1)}%</span></div><div class="flowBar" role="img" aria-label="Taker buy volume ${f.buyPct.toFixed(1)} percent; sell volume ${f.sellPct.toFixed(1)} percent${stale?'; stale sample':''}"><span style="width:${f.buyPct}%"></span><span style="width:${f.sellPct}%"></span></div><small>${demo?'ILLUSTRATIVE · ':stale?'STALE SAMPLE · ':''}${f.count.toLocaleString()} trades · ${Math.max(1,Math.round((f.newest-f.oldest)/1000))}s observed${large?' · latest ≤1,000 trades within 5m':''}</small>${large?`<p class="detailNote">Buy volume ${compact(f.buy)} ${m.symbol} · Sell volume ${compact(f.sell)} ${m.symbol}. ${new Date(f.oldest).toISOString().slice(11,19)}–${new Date(f.newest).toISOString().slice(11,19)} UTC. Aggressive buy/sell volume shares; every matched trade has both a buyer and a seller. This does not measure unique people.</p>`:''}</div>`;}
function flowSample(m){const f=m.flow?.summary();return f?.total&&(demo||fresh()&&Date.now()-f.newest<30000)?f:null;}
function pressureLists(ms){const buys=[],sells=[];for(const m of ms){const f=flowSample(m);if(!f)continue;if(f.buyPct>50)buys.push(m);if(f.sellPct>50)sells.push(m);}const sort=side=>(a,b)=>{const x=flowSample(a),y=flowSample(b);return y[side+'Pct']-x[side+'Pct']||(y.quoteBuy+y.quoteSell)-(x.quoteBuy+x.quoteSell);};buys.sort(sort('buy'));sells.sort(sort('sell'));return {buys,sells};}
function daily(m){return periodSnapshot(m,rangeKey,demo?(rangeKey==='1s'?Date.now():m.c?.at(-1)?.t+tf*60000||Date.now()):Date.now());}
function shownCandles(m){return daily(m)?.c??m.a?.candles.slice(-70)??[];}
function updateRangeLabels(){const r=RANGES[rangeKey];$('#rangeHint').textContent=r.live?'Live 1-second trade bars · last 2 minutes observed · empty seconds are not invented':`${r.label} history · ${r.minutes>=1440?'daily':r.minutes+' minute'} candles`;$('#mapDescription').textContent=r.live?'Observed one-second trade paths. Green above the first observed price; red below it.':`Price paths over ${r.label.toLowerCase()}. Green above the period’s first price; red below it.`;}
function profile(m){const ts=[...(m.flow?.trades.values()??[])].filter(t=>t.price);if(!ts.length)return '<div class="profileEmpty">Awaiting volume-at-price data</div>';const lo=Math.min(...ts.map(t=>t.price)),hi=Math.max(...ts.map(t=>t.price)),range=hi-lo||lo*.001,bins=Array.from({length:18},()=>({b:0,s:0}));for(const t of ts){const i=Math.min(17,Math.floor((t.price-lo)/range*18));bins[i][t.side==='Buy'?'b':'s']+=t.size;}const max=Math.max(...bins.flatMap(x=>[x.b,x.s]),1e-12);let out='<svg class="profile" viewBox="0 0 180 94" role="img" aria-label="Observed buy and sell volume by trade price"><path d="M90 0V94" stroke="#c3d2c4"/>';bins.forEach((b,i)=>{const y=88-i*4.8;out+=`<rect x="${90-b.b/max*84}" y="${y}" width="${b.b/max*84}" height="3.8" fill="#459f79"/><rect x="92" y="${y}" width="${b.s/max*82}" height="3.8" fill="#cc8585"/>`;});return out+'</svg>';}
function coinCard(m,i,side){const a=m.a,d=daily(m);return `<button class="coin ${side==='Sell'?'bear':''}" data-symbol="${m.symbol}"><div class="coinTop"><span>${m.symbol} ${saved.has(m.symbol)?'★':''}</span><span class="rankNum">${String(i+1).padStart(2,'0')}</span></div><div class="profileChange ${d?.change<0?'red':'green'}">${d?pct(d.change):'—'} <small>${RANGES[rangeKey].label.toUpperCase()}</small></div><div class="profileBias">${a?.bias??'Loading'} · ${a?a.score+' rule score':'…'}</div>${profile(m)}<div class="profilePrice">$${price(m.ticker.lastPrice)}</div>${flowMarkup(m)}<div class="coinQuality">${esc(dataQuality(m,{minutes:tf,demo}).state)} · ${m.c?.filter(x=>x.closed!==false).length??0} closed candles</div><div class="coinFoot"><span>${a?.zone?'OB '+price(a.zone.low)+'–'+price(a.zone.high):'Order block pending'}</span><span>${status(m)}</span></div></button>`;}
function featureCard(m,i,side){const a=m.a,d=daily(m);return `<button class="featureCard ${side==='Sell'?'sellFeature':''}" data-symbol="${m.symbol}"><div class="rankRow"><strong><small>0${i+1}</small> ${m.symbol}</strong><span class="conviction">${a?.score??'—'}</span></div><div class="featureTop"><div><span class="directionPill ${a?.bias==='Bearish'?'negative':''}">${a?.bias??'Loading'}</span><div class="featureChange ${d?.change<0?'red':'green'}">${d?pct(d.change):'—'}</div><span class="detailNote">$${price(m.ticker.lastPrice)} · ${RANGES[rangeKey].label} view</span></div><div class="featureChart">${a?chart(m):'<p>Loading chart</p>'}</div></div>${flowMarkup(m)}<div class="featureLevels"><span>ORDER BLOCK<b>${a?.zone?price(a.zone.low)+'–'+price(a.zone.high):'Awaiting zone'}</b></span><span>STOP<b>${a?.stop?price(a.stop):'—'}</b></span><span>TARGET<b>${a?.target?price(a.target):'—'}</b></span><span>R:R<b>${a?.rr?a.rr.toFixed(1):'—'}</b></span></div></button>`;}
function render(){const all=[...markets.values()],analyzed=all.filter(m=>m.a);$('#savedCount').textContent=saved.size;$('#bullCount').textContent=analyzed.filter(m=>m.a.bias==='Bullish').length;$('#bearCount').textContent=analyzed.filter(m=>m.a.bias==='Bearish').length;$('#readyCount').textContent=analyzed.filter(m=>status(m)==='Ready').length;$('#scanCount').textContent=`${analyzed.length} / ${symbols.length}`;const current=all.map(m=>flowSample(m)).filter(Boolean),qb=current.reduce((v,f)=>v+f.quoteBuy,0),qs=current.reduce((v,f)=>v+f.quoteSell,0),share=qb+qs?qb/(qb+qs)*100:null;$('#pulse').textContent=share==null?'—':share>50?'Buy side':share<50?'Sell side':'Balanced';$('#pulseText').textContent=share==null?'Waiting for trade samples':`${share.toFixed(1)}% buy / ${(100-share).toFixed(1)}% sell · sampled USDT volume`;const q=$('#search').value.toUpperCase();const visible=all.filter(m=>(!savedOnly||saved.has(m.symbol))&&m.symbol.includes(q)&&(filter!=='Ready'||status(m)==='Ready'));const {buys,sells}=pressureLists(visible);let out='';for(const [side,ms]of [['Buy',buys],['Sell',sells]]){if(filter==='Buy'&&side==='Sell'||filter==='Sell'&&side==='Buy')continue;out+=`<section class="marketGroup"><div class="groupHeading ${side==='Buy'?'green':'red'}"><h3>${side==='Buy'?'↗ TOP 20 · BUYING PRESSURE':'↘ TOP 20 · SELLING PRESSURE'}</h3><span>${Math.min(20,ms.length)} / 20 qualifying</span></div><div class="profileCards">${ms.slice(0,20).map((m,i)=>coinCard(m,i,side)).join('')||'<p class="empty">Waiting for fresh '+side.toLowerCase()+'-dominant trade samples. No entries are invented to fill this list.</p>'}</div></section>`;}$('#cards').innerHTML=out;for(const [ms,id,side]of [[buys,'buy20','Buy'],[sells,'sell20','Sell']]){$('#'+id).innerHTML=ms.slice(0,20).map((m,i)=>{const f=flowSample(m),v=side==='Buy'?f.buyPct:f.sellPct;return `<button data-symbol="${m.symbol}" class="compactRank ${side==='Sell'?'redRank':''}"><span>${String(i+1).padStart(2,'0')}</span><b>${m.symbol}</b><i style="width:${v}%"></i><em>${v.toFixed(1)}%</em></button>`;}).join('')||'<p class="empty">Awaiting fresh samples</p>';$('#'+(side==='Buy'?'buyCoverage':'sellCoverage')).textContent=Math.min(ms.length,20)+' qualifying';$('#'+(side==='Buy'?'bullList':'bearList')).innerHTML=ms.slice(0,3).map((m,i)=>featureCard(m,i,side)).join('')||'<p class="empty">No fresh '+side.toLowerCase()+'-dominant candidates.</p>';}drawMap(visible);}
function drawMap(ms){const data=ms.map(m=>({m,d:daily(m)})).filter(x=>x.d);if(!data.length){$('#marketMap').innerHTML='<div class="mapEmpty">Selected-range paths appear after history or live trades load</div>';$('#breadthStrip').innerHTML='';$('#directionBanner').textContent='Market direction · waiting for selected-range data';return;}const up=data.filter(x=>x.d.change>0).length,down=data.filter(x=>x.d.change<0).length;const {cap,clipped}=radarDomain(data.map(x=>x.d.change),$('#axisMode').value==='all'),w=1000,h=780,zero=up/data.length>.65?575:down/data.length>.65?205:390,top=32,bottom=740,clip=v=>Math.max(-cap,Math.min(cap,v)),y=v=>v>=0?zero-clip(v)/cap*(zero-top):zero-clip(v)/cap*(bottom-zero);$('#directionBanner').innerHTML=`<div><b class="${up>=down?'green':'red'}">${demo?'DEMO · ':''}${up>down?'↗ '+RANGES[rangeKey].label+': upward price bias':down>up?'↘ '+RANGES[rangeKey].label+': downward price bias':RANGES[rangeKey].label+': balanced price breadth'}</b><span>${up} above open · ${down} below open · ${data.length} crypto markets</span></div><small>${$('#axisMode').value==='all'?'Full':'Focus'} scale ±${cap.toFixed(1)}% · ${clipped} outside view, marked at edge · ${RANGES[rangeKey].label}</small>`;let svg=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-label="Selected-range crypto trajectories with crypto category column and endpoint profiles"><defs><linearGradient id="radarGreen" x1="0" y1="1" x2="0" y2="0"><stop stop-color="#f8fcf5"/><stop offset="1" stop-color="#d5ead3"/></linearGradient><linearGradient id="radarRed" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#fcfaf5"/><stop offset="1" stop-color="#f0d9d6"/></linearGradient><clipPath id="plotClip"><rect x="177" y="${top}" width="765" height="${bottom-top}"/></clipPath></defs><rect x="177" y="${top}" width="765" height="${zero-top}" fill="url(#radarGreen)" opacity=".35"/><rect x="177" y="${zero}" width="765" height="${bottom-zero}" fill="url(#radarRed)" opacity=".35"/>`;for(const v of [-cap,-cap/2,0,cap/2,cap])svg+=`<path d="M177 ${y(v)}H950" stroke="${v===0?'#8ca685':'#cbd9c5'}" stroke-width="${v===0?'1.1':'.6'}" stroke-dasharray="${v===0?'0':'3 5'}"/><text x="948" y="${y(v)+4}" fill="#879a7d" font-size="8">${v>0?'+':''}${v.toFixed(1)}%</text>`;const groups=new Map();for(const x of data){const g=category(x.m.symbol);if(!groups.has(g))groups.set(g,[]);groups.get(g).push(x);}const gs=[...groups].map(([name,xs])=>({name,change:xs.reduce((v,x)=>v+x.d.change,0)/xs.length,xs})).sort((a,b)=>b.change-a.change);svg+='<text x="10" y="30" font-size="8" fill="#67845b" letter-spacing="1">CRYPTO CATEGORIES</text>';gs.forEach((g,i)=>{const yy=65+i*49,col=g.change>=0?'#468b5a':'#bb797d';svg+=`<text x="10" y="${yy}" font-size="10" fill="#4d6345">${g.name.toUpperCase()}</text><text x="165" y="${yy}" font-size="9" fill="${col}" text-anchor="end">${pct(g.change)}</text><rect x="10" y="${yy+7}" width="${Math.max(3,Math.min(155,Math.abs(g.change)/cap*155))}" height="5" fill="${col}" opacity=".45"/><text x="10" y="${yy+25}" font-size="7" fill="#94a18b">${g.xs.length} coins · equal weighted</text>`;});const ref=Math.min(...data.map(x=>x.d.day)),end=Math.max(...data.map(x=>x.d.end)),span=Math.max(rangeKey==='1s'?1000:tf*60000,end-ref);const paths=data.map(({m,d})=>{const pts=[[177,zero],...d.c.map(c=>[177+Math.min(1,(c.t+(rangeKey==='1s'?1000:tf*60000)-ref)/span)*700,y((c.c/d.base-1)*100)]),[877,y(d.change)]];const path=linePath(pts);const col=d.change>=0?'#248353':'#bd5966';return `<g data-symbol="${m.symbol}" tabindex="0" role="button" aria-label="Open ${m.symbol}: ${pct(d.change)} over ${RANGES[rangeKey].label}" style="cursor:pointer"><title>${m.symbol}: ${pct(d.change)} over ${RANGES[rangeKey].label}${Math.abs(d.change)>cap?' · outside focus scale':''}</title><path d="${path}" fill="none" stroke="${col}" stroke-width="1.8" opacity=".82" vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-linejoin="round" clip-path="url(#plotClip)" class="marketLine"/><circle cx="877" cy="${y(d.change)}" r="2" fill="${col}"/><path d="M877 ${y(d.change)}h${Math.min(55,5+Math.abs(d.change)/cap*50)}" stroke="${col}" stroke-width="2.1" opacity=".45"/>${Math.abs(d.change)>cap?`<text x="805" y="${y(d.change)+(d.change>0?12:-5)}" font-size="7" fill="${col}">${m.symbol} ${pct(d.change)} ↕</text>`:''}</g>`;}).join('');svg+=paths+`<path d="M177 32V740 M938 32V740" stroke="#b2c6a7" stroke-width=".7"/><text x="177" y="769" fill="#8a9b88" font-size="9">${new Date(ref).toISOString().slice(rangeKey==='6M'||rangeKey==='1M'||rangeKey==='1w'?0:11,rangeKey==='6M'||rangeKey==='1M'||rangeKey==='1w'?10:19)} UTC</text><text x="852" y="769" fill="#8a9b88" font-size="9">NOW</text></svg>`;$('#marketMap').innerHTML=svg;let strip='<svg viewBox="0 0 1000 76" aria-label="Selected-range price breadth distribution"><path d="M25 46H975 M500 8V66" stroke="#c4d3bc"/>';for(const {m,d}of data){const x=500+clip(d.change)/cap*445,col=d.change>=0?'#3d8c5e':'#b47177',height=8+Math.min(24,Math.abs(d.change)/cap*24);strip+=`<g data-symbol="${m.symbol}" style="cursor:pointer"><path d="M${x} 46V${d.change>=0?46-height:46+height}" stroke="${col}" opacity=".4" stroke-width="2"/><circle cx="${x}" cy="46" r="2.3" fill="${col}" opacity=".8"/><title>${m.symbol} ${pct(d.change)} over ${RANGES[rangeKey].label}</title></g>`;}$('#breadthStrip').innerHTML=strip+`<text x="28" y="13" font-size="8" fill="#b07578">BEARISH · RANGE ${down}</text><text x="500" y="13" font-size="8" fill="#8b9a86">0%</text><text x="840" y="13" font-size="8" fill="#4b946c">BULLISH · RANGE ${up}</text></svg>`;}
async function api(path){const r=await fetch('https://api.bybit.com/v5/market/'+path,{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('Exchange HTTP '+r.status);const d=await r.json();if(d.retCode!==0)throw Error(d.retMsg||'Exchange error');return d.result.list;}
function feedState(text,ok){$('#feed').textContent=text;$('#dot').style.background=ok?'#309a68':'#bd8c50';}
async function start(){const gen=++generation;scanBusy=true;socket?.close();detailSocket?.close();markets.clear();lastTick=0;feedState(demo?'Demo · synthetic':'Connecting',false);$('#modeBadge').textContent=demo?'SYNTHETIC DEMO':'LIVE FEED';$('#demoBtn').textContent=demo?'Return to live':'Explore demo';$('#notice').textContent=demo?'DEMO MODE — synthetic historical candles and illustrative market values. These are not current trading opportunities.':'Loading Bybit USDT perpetual markets and closed-candle history…';render();if(demo){for(const [i,s] of symbols.entries()){const asset=ASSETS.find(x=>x[0]===s)??ASSETS[i%ASSETS.length];let c=demoCandles(asset[0],'15m');const step=RANGES[rangeKey].minutes*60000,end=Math.floor(Date.now()/step)*step;c=c.map((v,j)=>({...v,t:end-(c.length-j)*step}));if(i%2)c=c.map(x=>({...x,o:asset[2]*2-x.o,h:asset[2]*2-x.l,l:asset[2]*2-x.h,c:asset[2]*2-x.c}));const a=setup(c);const seconds=new SecondBars();seconds.add(Array.from({length:120},(_,j)=>({i:'demo-'+j,T:Date.now()-(120-j)*1000,p:c.at(-1).c*(1+Math.sin(j/12)*.003),v:1+j%5})));const flow=new TradeFlow();flow.add(Array.from({length:40},(_,j)=>({i:String(j),T:Date.now()-(40-j)*1000,S:(j+i)%10<(i%2?3:7)?'Buy':'Sell',v:(j%7+1),p:c.at(-1).c*(1+(j%9-4)*.0003)})));markets.set(s,{symbol:s,c,a,flow,seconds,ticker:{lastPrice:c.at(-1).c,price24hPcnt:asset[3]/100,openInterest:null,fundingRate:null}});}lastTick=Date.now();feedState('Demo · synthetic',false);scanBusy=false;render();return;}try{const ts=await api('tickers?category=linear');if(gen!==generation)return;symbols=ts.filter(t=>/^[A-Z0-9]+USDT$/.test(t.symbol)&&CRYPTO_UNIVERSE.has(t.symbol.slice(0,-4))&&+t.turnover24h>0).sort((a,b)=>+b.turnover24h-+a.turnover24h).slice(0,60).map(t=>t.symbol.slice(0,-4));for(const s of symbols){const t=ts.find(x=>x.symbol===s+'USDT');if(t)markets.set(s,{symbol:s,ticker:t,flow:new TradeFlow(),seconds:new SecondBars()});}render();let queue=[...markets.values()];await Promise.all(Array.from({length:3},async()=>{while(queue.length){const m=queue.shift();try{const rows=await api(`kline?category=linear&symbol=${m.symbol}USDT&interval=${RANGES[rangeKey].interval}&limit=300`);if(gen!==generation)return;m.c=parseBybit(rows,tf);m.a=setup(m.c);scheduleRender();try{const trades=await api(`recent-trade?category=linear&symbol=${m.symbol}USDT&limit=1000`);if(gen!==generation)return;m.flow.add(trades);m.seconds.add(trades);scheduleRender();}catch{m.flowError=true;}}catch(e){m.error=e.message;}}}));if(gen!==generation)return;connect(gen);$('#notice').textContent='Live exchange data · scores use closed candles · buy/sell bars use observed taker volume · opening a coin adds market depth.';}catch(e){if(gen!==generation)return;feedState('Feed unavailable',false);$('#notice').textContent='Live data could not be reached: '+e.message+'. Retry or choose Explore demo. No live signals are being generated.';}finally{if(gen===generation){scanBusy=false;render();}}}
function connect(gen){socket=new WebSocket('wss://stream.bybit.com/v5/public/linear');socket.onopen=()=>{if(gen!==generation)return;socket.send(JSON.stringify({op:'subscribe',args:[...markets.keys()].flatMap(s=>['tickers.'+s+'USDT',`kline.${RANGES[rangeKey].interval}.${s}USDT`,'publicTrade.'+s+'USDT'])}));};socket.onmessage=e=>{if(gen!==generation)return;let d;try{d=JSON.parse(e.data);}catch{return;}if(!d.topic||!d.data)return;lastTick=Date.now();feedState('Live · Bybit',true);const s=d.topic.split('.').at(-1).replace(/USDT$/,'');const m=markets.get(s);if(!m)return;if(d.topic.startsWith('publicTrade.')){m.flow.add(d.data);m.seconds.add(d.data);}else if(d.topic.startsWith('tickers.'))m.ticker={...m.ticker,...d.data};else if(m.c){for(const k of d.data){const v={t:+k.start,o:+k.open,h:+k.high,l:+k.low,c:+k.close,v:+k.volume,closed:!!k.confirm};const i=m.c.findIndex(x=>x.t===v.t);if(i>=0)m.c[i]=v;else m.c.push(v);m.c=m.c.slice(-300);}m.a=setup(m.c);}scheduleRender();};socket.onclose=()=>{if(gen===generation&&!demo){feedState('Disconnected · retry',false);lastTick=0;render();if($('#detail').open)renderDetail();}};socket.onerror=()=>{if(gen===generation)$('#notice').textContent='Live stream unavailable. Signals are disabled until the stream reconnects. Use Refresh to retry.';};}
function chart(m){const c=shownCandles(m).length?shownCandles(m):m.a.candles.slice(-70),w=900,h=300,left=12,right=92,top=22,bottom=25,z=rangeKey==='1s'?null:m.a.zone;const levels=referenceLevels(m.a.candles);const vals=c.flatMap(x=>[x.h,x.l]).concat(z?[z.low,z.high]:[]).concat(rangeKey==='1s'?[]:Object.values(levels).filter(Number.isFinite)).concat(rangeKey==='1s'?[]:[m.a.stop,m.a.target].filter(v=>Number.isFinite(v)&&v>0));const lo=Math.min(...vals),hi=Math.max(...vals),range=hi-lo||1,y=v=>top+(hi-v)/range*(h-top-bottom),dx=(w-left-right)/c.length;let out=`<svg class="chart" role="img" aria-label="${m.symbol} candlestick chart with order-block zone and VWAP" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">`;for(let i=0;i<5;i++){const v=lo+range*i/4;out+=`<path d="M12 ${y(v)}H810" stroke="#e1e8df"/><text x="820" y="${y(v)+3}" font-size="9" fill="#8a9786">${price(v)}</text>`;}if(z)out+=`<rect x="12" y="${y(z.high)}" width="798" height="${Math.max(2,y(z.low)-y(z.high))}" fill="${m.a.bias==='Bullish'?'#cae7cd':'#efcdca'}" opacity=".7"/><text x="20" y="${y(z.high)-4}" font-size="9" fill="#5e8564">ORDER BLOCK ${price(z.low)} – ${price(z.high)}</text>`;if(m.a.vwap>=lo&&m.a.vwap<=hi)out+=`<path d="M12 ${y(m.a.vwap)}H810" stroke="#b7944f" stroke-dasharray="5 4"/><text x="700" y="${y(m.a.vwap)-4}" font-size="9" fill="#ad8d4a">UTC VWAP</text>`;const annotations=[['STOP',m.a.stop,'#bd7676'],['TARGET',m.a.target,'#539263'],['S1',levels.s1,'#438469'],['S2',levels.s2,'#438469'],['R1',levels.r1,'#ba5c60'],['R2',levels.r2,'#ba5c60']].filter(x=>Number.isFinite(x[1])&&x[1]>=lo&&x[1]<=hi).sort((a,b)=>y(a[1])-y(b[1]));let labelY=10;for(const [name,value,col]of annotations){const yy=y(value),ly=Math.max(yy-4,labelY);labelY=ly+12;out+=`<path d="M12 ${yy}H810" stroke="${col}" stroke-dasharray="4 4" opacity=".7"/><rect x="582" y="${ly-9}" width="115" height="12" fill="#fbfcfa" opacity=".9"/><text x="585" y="${ly}" font-size="9" fill="${col}">${name} ${price(value)}</text>`;}c.forEach((v,i)=>{const x=left+(i+.5)*dx,color=v.c>=v.o?'#42966c':'#c67572';out+=`<path d="M${x} ${y(v.h)}V${y(v.l)}" stroke="${color}" stroke-width="1.6"/><rect x="${x-dx*.28}" y="${y(Math.max(v.o,v.c))}" width="${dx*.56}" height="${Math.max(1,Math.abs(y(v.o)-y(v.c)))}" fill="${color}"/>`;});out+=`<text x="12" y="295" font-size="9" fill="#8a9786">${new Date(c[0].t).toISOString().slice(5,16).replace('T',' ')} UTC</text><text x="660" y="295" font-size="9" fill="#8a9786">${new Date(c.at(-1).t).toISOString().slice(5,16).replace('T',' ')} UTC</text></svg>`;return out;}
function horizonTabs(){return `<div class="horizonTabs" role="group" aria-label="Forecast horizon">${[2,3,7].map(h=>`<button data-horizon="${h}" class="${forecastHorizon===h?'chosen':''}" aria-pressed="${forecastHorizon===h}">${h===7?'1 week':h+' days'}</button>`).join('')}</div>`;}
function forecastMarkup(m){const f=m.forecasts?.[forecastHorizon]??m.forecast;if(!f)return `<section class="forecastPanel"><div class="forecastTitle"><h3>AI / ML · Price outlook</h3><span>Historical-pattern model</span></div><p class="detailNote">${m.forecastLoading?'Analyzing daily price history…':'Daily forecast will load when this coin is opened.'}</p></section>`;if(!f.available)return `<section class="forecastPanel"><h3>Forecast unavailable</h3><p class="detailNote">${esc(f.reason)}</p><button id="retryForecast">Retry daily history</button></section>`;const v=f.validation,direction=f.median>0?'Upward estimate':f.median<0?'Downward estimate':'Flat estimate';return `<section class="forecastPanel"><div class="forecastTitle"><div><p class="eyebrow">${demo?'SYNTHETIC DEMO · ':''}AI / ML · HISTORICAL PATTERN MATCHING</p><h3>${forecastHorizon===7?'One-week':forecastHorizon+'-day'} outlook</h3></div><span class="pill">${f.stale?'STALE HISTORY':f.hasEdge?'Experimental estimate':'No demonstrated edge'}</span></div>${horizonTabs()}<div class="forecastHeadline"><div><span class="${f.median>=0?'green':'red'}">${direction}</span><strong class="${f.median>=0?'green':'red'}">${pct(f.median)}</strong><small>Estimated endpoint $${price(f.target)}</small></div><div><label>HISTORICAL ANALOGUE RANGE</label><b>$${price(f.lowPrice)} – $${price(f.highPrice)}</b><small>${pct(f.low)} to ${pct(f.high)} · 10th–90th percentile of matched outcomes</small></div></div>${forecastChart(f)}<div class="forecastStats"><span>Backtest direction hit rate<b>${v.n?v.direction.toFixed(1)+'%':'—'}</b><small>${v.n} historical ${f.horizon??7}-day tests</small></span><span>Mean absolute error<b>${v.mae==null?'—':v.mae.toFixed(2)+' pp'}</b><small>Unchanged-price baseline ${v.baselineMae?.toFixed(2)??'—'} pp</small></span><span>Range coverage<b>${v.n?v.coverage.toFixed(1)+'%':'—'}</b><small>Always-up direction baseline ${v.alwaysUp?.toFixed(1)??'—'}%</small></span></div><p class="forecastVerdict">${f.stale?'Daily history is stale. Refresh before considering this estimate.':f.hasEdge?'This model had lower historical point-forecast error than the unchanged-price baseline over the displayed tests.':'The model has not demonstrated lower error than the unchanged-price baseline with at least 12 tests at this horizon. Treat this outlook as exploratory.'}</p><p class="detailNote">Based on ${f.days} closed daily candles and ${f.neighbors} matched historical ${f.horizon??7}-day periods. ${f.upShare.toFixed(1)}% of weighted matched outcomes rose; this is not a calibrated probability. Forecast reference: $${price(f.price)} at ${new Date(f.asOf).toISOString().slice(0,16).replace('T',' ')} UTC → ${new Date(f.targetTime).toISOString().slice(0,16).replace('T',' ')} UTC. This estimates the price at the endpoint, not the highest price touched during the period. Validation uses only earlier data at each origin. Historical results do not establish future accuracy.</p></section>`;}
function forecastChart(f){const base=f.price,values=[base,f.lowPrice,f.highPrice,f.target],lo=Math.min(...values)*.99,hi=Math.max(...values)*1.01,y=p=>135-(p-lo)/(hi-lo||1)*112;return `<svg class="forecastChart" viewBox="0 0 720 165" role="img" aria-label="${f.horizon??7}-day endpoint estimate and historical analogue range"><path d="M35 ${y(base)}H655" stroke="#b7c6ad" stroke-dasharray="4 5"/><polygon points="35,${y(base)} 600,${y(f.highPrice)} 600,${y(f.lowPrice)}" fill="#b9d9b7" opacity=".3"/><path d="M35 ${y(base)}L600 ${y(f.target)}" stroke="#56845a" stroke-width="2" stroke-dasharray="5 4"/><path d="M600 ${y(f.highPrice)}V${y(f.lowPrice)}" stroke="#8cb18a"/><circle cx="600" cy="${y(f.target)}" r="4" fill="#56845a"/><text x="610" y="${y(f.highPrice)+3}" font-size="10" fill="#74876b">${price(f.highPrice)}</text><text x="610" y="${y(f.lowPrice)+3}" font-size="10" fill="#74876b">${price(f.lowPrice)}</text><text x="35" y="158" font-size="9" fill="#8a9981">LAST DAILY CLOSE</text><text x="555" y="158" font-size="9" fill="#8a9981">DAY ${f.horizon??7} · ESTIMATE</text></svg>`;}
async function loadForecast(m,force=false){if(m.forecastLoading||m.forecast&&!force)return;m.forecastLoading=true;const gen=generation;try{if(demo){const c=demoDaily(m.symbol);m.forecasts=Object.fromEntries([2,3,7].map(h=>[h,forecastWeek(c,{horizon:h})]));m.forecast=m.forecasts[7];m.historyStatus='Demo forecast · not recorded in live accuracy.';}else{const res=await fetch('/api/predictions/record',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({symbol:m.symbol}),signal:AbortSignal.timeout(20000)}),d=await res.json();if(!res.ok)throw Error(d.error||'Prediction record unavailable');if(gen!==generation)return;m.forecasts=d.forecasts;m.forecast=d.forecasts[7];m.historyStatus=d.records.length?`Saved permanently: ${d.records.length} forecast horizons. Results will be checked after each target close.`:'No record saved: verified history is insufficient.';}}catch(e){m.historyStatus='Not saved to the live record. '+e.message;try{const c=parseBybit(await api(`kline?category=linear&symbol=${m.symbol}USDT&interval=D&limit=1000`),1440);if(gen!==generation)return;m.forecasts=Object.fromEntries([2,3,7].map(h=>[h,forecastWeek(c,{horizon:h})]));m.forecast=m.forecasts[7];}catch{m.forecast={available:false,reason:'Verified daily history is unavailable. No forecast was added to accuracy history.'};}}finally{m.forecastLoading=false;if(gen===generation&&selected===m.symbol&&$('#detail').open)renderDetail();}}
async function loadResearch(m){if(m.researchLoading||m.research)return;m.researchLoading=true;const gen=generation;try{if(demo){m.research={demo:true};return;}const r=await fetch('/api/research?symbol='+encodeURIComponent(m.symbol),{signal:AbortSignal.timeout(25000)}),d=await r.json();if(!r.ok)throw Error(d.error||'Research unavailable');if(gen===generation)m.research=d;}catch(e){m.researchError=e.message;}finally{m.researchLoading=false;if(gen===generation&&selected===m.symbol&&$('#detail').open)renderDetail();}}
function researchMarkup(m){const r=m.research;const head='<p class="eyebrow">NEWS & MARKET CATALYSTS</p><h3>What could explain the move?</h3>';if(!r)return `<section class="researchPanel">${head}<p role="status">${esc(m.researchError||'Checking recent reporting, announcements and market context…')}</p>${m.researchError?'<button id="retryResearch">Retry research</button>':''}</section>`;if(r.demo)return `<section class="researchPanel">${head}<p>Synthetic demo: real news cannot explain these simulated prices. Switch to the live market for sourced research.</p></section>`;const article=a=>`<article class="newsArticle"><div class="newsMeta">${esc(a.official?'Official announcement':a.reportedDriver?'Reported explanation':'Related reporting')} · ${esc(a.topic)} · ${esc(a.articleAccess??'Feed excerpt only')}</div><a href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">${esc(a.title)} ↗</a><p class="newsMeta">${esc(a.publisher)} · ${new Date(a.publishedAt).toISOString().slice(0,16).replace('T',' ')} UTC${a.discovery==='Google News'?' · indexed via Google News':''}</p>${a.excerpt?`<p>${esc(a.excerpt)}</p>`:''}</article>`;return `<section class="researchPanel">${head}<p class="researchConclusion">${esc(r.conclusion)}</p>${r.reportedDriver?`<p class="detailNote">Report behind this assessment: <a href="${esc(r.reportedDriver.url)}" target="_blank" rel="noopener noreferrer">${esc(r.reportedDriver.title)}</a></p>`:''}<p class="detailNote">Chart: ${RANGES[rangeKey].label}. News lookback: 7 days. Market comparison: 24 hours. These time windows differ; a headline does not establish the cause of this chart movement.</p>${r.notes.map(n=>`<p>${esc(n)}</p>`).join('')}${!r.market?'<p class="detailNote">Live market comparison unavailable.</p>':''}${r.catalysts?.length?`<div class="catalystGrid">${r.catalysts.map(c=>`<article><b>${esc(c.topic)}</b><p>${esc(c.assessment)}</p><small>${c.sources.map(x=>esc(x.publisher)).join(' · ')}</small></article>`).join('')}</div>`:''}<h4>Coin-specific reporting & announcements</h4>${r.articles.length?r.articles.map(article).join(''):'<p>No matching recent reports found in the accessible feeds. No news-based cause can be established.</p>'}${r.marketArticles.length?`<h4>Broader market context</h4>${r.marketArticles.map(article).join('')}`:''}<details><summary>Research coverage · ${r.coverage.filter(x=>x.status==='checked').length}/${r.coverage.length} sources reached</summary><p>${esc(r.scope)}</p><ul>${r.coverage.map(c=>`<li>${esc(c.name)}: ${esc(c.status)}</li>`).join('')}</ul><p>Checked ${new Date(r.checkedAt).toISOString().slice(0,16).replace('T',' ')} UTC · cached for up to 5 minutes. Quantitative forecasts use historical prices; this news context is not incorporated into that model.</p></details></section>`;}
async function loadIntelligence(m,force=false){if(m.intelligenceLoading||m.intelligence&&!force)return;m.intelligenceLoading=true;const gen=generation;try{if(demo)return;const r=await fetch('/api/intelligence?symbol='+encodeURIComponent(m.symbol),{signal:AbortSignal.timeout(20000)});const d=await r.json();if(!r.ok)throw Error(d.error||'Exchange evidence unavailable');if(gen!==generation)return;
// The user's browser may reach Bybit even when server egress cannot.
const missing=d.coverage?.some(x=>!x.available&&['oi','price','accounts','funding','bybitSpot','bybitPerp'].includes(x.name));
if(missing){const jobs={oi:`open-interest?category=linear&symbol=${m.symbol}USDT&intervalTime=1h&limit=3`,price:`kline?category=linear&symbol=${m.symbol}USDT&interval=60&limit=5`,accounts:`account-ratio?category=linear&symbol=${m.symbol}USDT&period=1h&limit=2`,funding:`funding/history?category=linear&symbol=${m.symbol}USDT&limit=6`,bybitSpot:`recent-trade?category=spot&symbol=${m.symbol}USDT&limit=60`,bybitPerp:`recent-trade?category=linear&symbol=${m.symbol}USDT&limit=1000`},rows={};await Promise.all(Object.entries(jobs).filter(([k])=>d.coverage.find(x=>x.name===k)?.available===false).map(async([k,path])=>{try{rows[k]=await api(path);const cov=d.coverage.find(x=>x.name===k);cov.available=true;cov.transport='Browser direct';}catch{}}));if(gen!==generation)return;const derived=derivativeEvidence(rows);if(derived.position)d.position=derived.position;if(derived.accounts)d.accounts=derived.accounts;if(derived.funding.length)d.funding=derived.funding;for(const [key,market] of [['bybitSpot','Spot'],['bybitPerp','Perpetual']])if(rows[key]){const v=d.venues.find(v=>v.exchange==='Bybit'&&v.market===market);v.available=true;v.sample=samplePressure(rows[key].map(x=>({id:x.execId,time:+x.time,size:+x.size,price:+x.price,side:x.side?.toLowerCase()})));}d.browserFallback=true;}
if(gen===generation)m.intelligence=d;}catch(e){m.intelligenceError=e.message;}finally{m.intelligenceLoading=false;if(gen===generation&&selected===m.symbol&&$('#detail').open)renderDetail();}}
function referenceMarkup(m){const {buys,sells}=pressureLists([...markets.values()]),buy=flowSample(m)?.buyPct>50,list=buy?buys:sells,rank=list.findIndex(x=>x.symbol===m.symbol)+1;return qualityPanel(m,{minutes:tf,duration:RANGES[rangeKey].duration,demo})+analysisCard(m,{rank,side:buy?'buy pressure':'sell pressure',rangeLabel:RANGES[rangeKey].label,demo,status:status(m),change:daily(m)?.change})+'<div id="proChartMount"></div>'+intelligencePanel(m,{demo,liquidations});}
