function renderDetail(){const m=markets.get(selected);if(!m?.a||proChart?.drag||document.activeElement?.matches('.chartNote'))return;const oldChart=$('#proChartMount'),scroll=$('#detail').scrollTop;const a=m.a;const isFresh=fresh();const imbalance=book&&Date.now()-detailUpdated<30000?(book.b.reduce((s,x)=>s+x[1],0)-book.a.reduce((s,x)=>s+x[1],0))/(book.b.reduce((s,x)=>s+x[1],0)+book.a.reduce((s,x)=>s+x[1],0)||1)*100:null;$('#detailContent').innerHTML=`<button class="close" id="closeDetail" aria-label="Close chart">✕</button><div class="detailHead"><div><p class="eyebrow">${demo?'SYNTHETIC DEMO':'BYBIT · USDT PERPETUAL'} · ${RANGES[rangeKey].label.toUpperCase()} VIEW</p><h2>${m.symbol} / USDT <span class="pill">${a.bias}</span></h2><p>${a.reason}</p></div><button id="saveCoin">${saved.has(selected)?'★ Watching':'☆ Watch coin'}</button></div>${referenceMarkup(m)}${checksMarkup(m,{demo,book,at:detailUpdated})}${strategyMarkup(m)}${forecastMarkup(m)}<div class="historySaveStatus" role="status">${esc(m.historyStatus??(m.forecastLoading?'Verifying and saving forecast…':'Loading forecast…'))}<button id="viewCoinHistory">View live track record ↗</button></div>${researchMarkup(m)}<details class="technicalEvidence"><summary>Technical ranking evidence</summary>${evidenceMarkup(m)}</details><section class="flowDetail"><h3>Taker buying vs selling</h3>${flowMarkup(m,true)}</section><p class="reasons">${a.zone?'✓ Active '+a.bias.toLowerCase()+' order-block zone':'○ No active matching order-block zone'} · ${a.confirmed?'✓ Retest confirmed':'○ Waiting for retest confirmation'}<br>Relative volume ${a.volume.toFixed(2)}× · 5-candle momentum ${pct(a.momentum)} · UTC VWAP $${price(a.vwap)}<br>Session taker delta: ${demo?'—':compact(tradeDelta)+' '+selected} · Top-50 book imbalance: ${imbalance==null?'Waiting for depth':pct(imbalance)}</p><p class="detailNote">${!isFresh?'STALE / DISCONNECTED — entry signals disabled. ':''}${status(m)==='Ready'?'Ready under the displayed rules.':'WAIT — reference levels are conditional, not an active entry signal.'} Candles end ${new Date(a.last.t+tf*60000).toISOString().replace('T',' ').slice(0,19)} UTC. Trade delta starts when this detail opens; it is not historical daily delta. Score is not a probability of profit.</p>`;if(oldChart&&proChart?.symbol===m.symbol&&proChart.demo===demo&&proChart.accountUser===account.user?.id){$('#proChartMount').replaceWith(oldChart);}else{proChart?.destroy();proChart=new ProChart($('#proChartMount'),{symbol:m.symbol,demo,getMarket:()=>markets.get(m.symbol),initial:rangeKey==='1s'?'1s':'5m'});}$('#detail').scrollTop=scroll;$('#closeDetail').onclick=()=>$('#detail').close();$('#viewCoinHistory').onclick=()=>{$('#detail').close();$('#historySymbol').value=m.symbol;showHistory();};if($('#refreshChecks'))$('#refreshChecks').onclick=()=>loadChecks(m,true);if($('#runStrategy'))$('#runStrategy').onclick=()=>runStrategy(m);if($('#retryIntelligence'))$('#retryIntelligence').onclick=()=>loadIntelligence(m,true);if($('#retryResearch'))$('#retryResearch').onclick=()=>loadResearch(m);if($('#retryForecast'))$('#retryForecast').onclick=()=>loadForecast(m,true);document.querySelectorAll('[data-horizon]').forEach(b=>b.onclick=()=>{forecastHorizon=+b.dataset.horizon;renderDetail();});$('#saveCoin').onclick=async()=>{if(!account.user){account.open();return;}const next=new Set(saved);next.has(selected)?next.delete(selected):next.add(selected);try{await account.savePrefs({...account.prefs,watchlist:[...next]});saved=next;render();renderDetail();}catch(e){$('#notice').textContent='Watchlist not saved: '+e.message;}};}
function openDetail(s){const m=markets.get(s);if(!m?.a){$('#notice').textContent='Candle history is not available for '+s+' yet. Refresh the live scan to retry.';return;}if($('#detail').open&&selected===s)return;if($('#detail').open)$('#detail').close();if(proChart?.symbol!==s){proChart?.destroy();proChart=null;$('#proChartMount')?.remove();}selected=s;liquidations={long:0,short:0,start:Date.now(),connected:false};tradeDelta=0;book=null;detailUpdated=0;detailSocket?.close();renderDetail();$('#detail').showModal();loadForecast(m);loadResearch(m);loadIntelligence(m);loadChecks(m);if(demo)return;const ds=detailSocket=new WebSocket('wss://stream.bybit.com/v5/public/linear');ds.onopen=()=>{liquidations.connected=true;ds.send(JSON.stringify({op:'subscribe',args:['publicTrade.'+s+'USDT','orderbook.50.'+s+'USDT','allLiquidation.'+s+'USDT']}));};ds.onclose=()=>{if(ds===detailSocket)liquidations.connected=false;};ds.onmessage=e=>{if(ds!==detailSocket)return;let d;try{d=JSON.parse(e.data);}catch{return;}if(d.topic?.startsWith('allLiquidation')){const totals=liquidationTotals(Array.isArray(d.data)?d.data:[]);liquidations.long+=totals.long;liquidations.short+=totals.short;}else if(d.topic?.startsWith('publicTrade')){for(const t of d.data)tradeDelta+=(t.S==='Buy'?1:-1)*+t.v;}else if(d.topic?.startsWith('orderbook')){if(d.type==='snapshot'||d.data.u===1)book={b:d.data.b.map(x=>x.map(Number)),a:d.data.a.map(x=>x.map(Number))};else if(book){for(const side of ['b','a'])for(const [ps,vs] of d.data[side]){const p=+ps,v=+vs,i=book[side].findIndex(x=>x[0]===p);if(!v){if(i>=0)book[side].splice(i,1);}else if(i>=0)book[side][i]=[p,v];else book[side].push([p,v]);}book.b.sort((a,b)=>b[0]-a[0]);book.a.sort((a,b)=>a[0]-b[0]);book.b=book.b.slice(0,50);book.a=book.a.slice(0,50);}detailUpdated=Date.now();}scheduleRender();};}
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#detail').close();if((e.key==='Enter'||e.key===' ')&&e.target.matches('g[data-symbol]')){e.preventDefault();openDetail(e.target.dataset.symbol);}});document.addEventListener('click',e=>{const coin=e.target.closest('[data-symbol]');if(coin)openDetail(coin.dataset.symbol);const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b===f));render();}});$('#detail').addEventListener('close',()=>{if(!$('#detail').open){detailSocket?.close();proChart?.destroy();proChart=null;$('#proChartMount')?.remove();selected=null;}});$('#axisMode').onchange=render;$('#search').oninput=render;$('#refresh').onclick=()=>start();$('#demoBtn').onclick=()=>{demo=!demo;start();};$('#timeframe').onchange=e=>{rangeKey=e.target.value;tf=RANGES[rangeKey].minutes;$('#detail').close();updateRangeLabels();start();};$('#savedTab').onclick=()=>{showMarket();savedOnly=true;$('#savedTab').classList.add('active');$('#radarTab').classList.remove('active');render();};$('#radarTab').onclick=()=>{showMarket();savedOnly=false;$('#radarTab').classList.add('active');$('#savedTab').classList.remove('active');render();};$('#rulesBtn').onclick=()=>$('#method').showModal();$('#closeRules').onclick=()=>$('#method').close();setInterval(()=>{$('#clock').textContent=new Date().toISOString().slice(11,19)+' UTC';if(!scanBusy)render();if(!demo&&lastTick&&!fresh()){feedState('Stale · retry',false);render();if($('#detail').open)renderDetail();}for(const ws of [socket,detailSocket])if(ws?.readyState===1)ws.send(JSON.stringify({op:'ping'}));},10000);updateRangeLabels();start();

function showMarket(){$('#historyView').hidden=true;$('#marketView').hidden=false;$('#historyTab').classList.remove('active');}
function showHistory(){$('#marketView').hidden=true;$('#historyView').hidden=false;$('#historyTab').classList.add('active');$('#savedTab').classList.remove('active');$('#radarTab').classList.remove('active');loadHistory(true);}
const historyDate=t=>new Date(t).toISOString().slice(0,16).replace('T',' ');
let historyBusy=false;
async function loadHistory(check=false){if(historyBusy)return;fetch('/api/maintenance').then(r=>r.json()).then(d=>{const el=$('#trackingStatus');if(el)el.textContent=d.last?.finished_at?'Last maintenance: '+historyDate(d.last.finished_at)+' UTC. Health: '+(d.health?.state??'Unknown')+'. '+(d.health?.issues?.join('; ')??'')+' '+d.note:'Automatic tracking is prepared but no completed unattended run is recorded yet.';}).catch(()=>{});historyBusy=true;$('#checkResults').disabled=true;$('#historyStatus').textContent=check?'Checking forecasts whose target time has passed…':'Loading prediction history…';try{let outcome='';if(check){try{const r=await fetch('/api/predictions/evaluate',{method:'POST',signal:AbortSignal.timeout(45000)}),d=await r.json();if(r.ok)outcome=`${d.completed} new results verified. ${d.unavailable} checks awaiting exchange data. `;else outcome='Outcome checks are currently unavailable. ';}catch{outcome='Outcome checks could not finish. ';}}const params=new URLSearchParams(),h=$('#historyHorizon').value,s=$('#historySymbol').value.trim().toUpperCase();if(h)params.set('horizon',h);if(s)params.set('symbol',s);const r=await fetch('/api/predictions?'+params,{signal:AbortSignal.timeout(15000)}),d=await r.json();if(!r.ok)throw Error(d.error||'History unavailable');renderCoinEvaluation(d.byCoin??[]);$('#historySummary').innerHTML=d.summary.map(v=>`<article><label>${v.horizon===7?'ONE WEEK':v.horizon+' DAYS'} · LIVE RESULTS</label><strong>${v.accuracy==null?'Pending':v.accuracy.toFixed(1)+'%'}</strong><p>${v.directional_tests} directional tests · ${v.completed} completed / ${v.total} saved</p><small>${v.total-v.completed-v.awaiting_data} pending · ${v.awaiting_data} awaiting data<br>Mean error ${v.mean_error_pp==null?'—':v.mean_error_pp.toFixed(2)+' pp'} · unchanged-price baseline ${v.unchanged_baseline_error_pp==null?'—':v.unchanged_baseline_error_pp.toFixed(2)+' pp'}<br>Outcome range coverage ${v.range_coverage==null?'—':v.range_coverage.toFixed(1)+'%'}</small></article>`).join('')||'<article><label>LIVE ACCURACY</label><strong>Not yet measured</strong><p>Open a live coin to save its forecasts. The first results appear after their target times.</p></article>';$('#historyRows').innerHTML=d.rows.map(v=>{const done=v.actualPrice!=null,status=done?'Completed':v.dueAt<=d.now?'Awaiting exchange data':'Pending',hit=v.directionHit==null?'Flat / unscored':v.directionHit?'Correct direction':'Wrong direction';return `<tr><td><b>${esc(v.symbol)}</b><small>${v.horizon===7?'1 week':v.horizon+' days'}</small></td><td>${historyDate(v.createdAt)}<small>Target ${historyDate(v.dueAt)}<br>Reference ${historyDate(v.asOf)}</small></td><td class="${v.predictedPct>=0?'green':'red'}">${pct(v.predictedPct)} → $${price(v.targetPrice)}<small>From $${price(v.referencePrice)}<br>Range $${price(v.lowPrice)}–$${price(v.highPrice)}</small></td><td>${done?'$'+price(v.actualPrice)+' · '+pct(v.actualPct):'—'}<small>${done?'Target daily close · checked '+historyDate(v.evaluatedAt):'Outcome is not scored yet'}</small></td><td class="${done&&v.directionHit===1?'green':done&&v.directionHit===0?'red':''}">${done?hit:'—'}<small>${done?v.errorPp.toFixed(2)+' pp error':''}</small></td><td><span class="historyPill">${status}</span><small>${esc(v.modelVersion)}</small></td></tr>`;}).join('')||'<tr><td colspan="6" class="empty">No live predictions have been recorded for this filter yet.</td></tr>';$('#historyStatus').textContent=outcome+`Updated ${historyDate(d.now)} UTC. Each original forecast is preserved; pending and unverified outcomes do not count as accurate.`;}catch(e){$('#historyStatus').textContent=e.message;$('#historyRows').innerHTML='<tr><td colspan="6" class="empty">History could not load. Retry to check the permanent record.</td></tr>';}finally{historyBusy=false;$('#checkResults').disabled=false;}}
$('#historyTab').onclick=showHistory;$('#checkResults').onclick=()=>loadHistory(true);$('#filterHistory').onclick=()=>loadHistory(false);$('#historyHorizon').onchange=()=>loadHistory(false);

function renderCoinEvaluation(rows){let box=$('#coinEvaluation');if(!box){box=document.createElement('section');box.id='coinEvaluation';$('#historySummary').after(box);}box.innerHTML='<h3>Performance by coin & forecast horizon</h3><p class="detailNote">Live completed outcomes only. Fewer than 30 directional tests is a small sample; even larger samples do not guarantee future performance.</p><div class="comparisonWrap"><table class="comparisonTable"><thead><tr><th>Coin / horizon</th><th>Completed / saved</th><th>Direction accuracy</th><th>Model error</th><th>Unchanged-price error</th><th>Evidence</th></tr></thead><tbody>'+rows.map(r=>`<tr><td>${esc(r.symbol)} / ${r.horizon}d</td><td>${r.completed} / ${r.total}</td><td>${r.accuracy==null?'Pending':r.accuracy.toFixed(1)+'%'} (${r.directional_tests} tests)</td><td>${r.mean_error_pp==null?'—':r.mean_error_pp.toFixed(2)+' pp'}</td><td>${r.unchanged_baseline_error_pp==null?'—':r.unchanged_baseline_error_pp.toFixed(2)+' pp'}</td><td>${r.directional_tests<30?'Small sample':'30+ directional tests'}${r.mean_error_pp!=null&&r.unchanged_baseline_error_pp!=null?'<br>'+(r.mean_error_pp<r.unchanged_baseline_error_pp?'Lower error than baseline':'Has not beaten baseline'):''}</td></tr>`).join('')+'</tbody></table></div>'+(rows.length?'':'<p class="empty">No live forecasts recorded for this filter.</p>');}

function strategyMarkup(m){const r=m.strategy;return `<section class="strategyPanel"><div class="panelHeading"><h3>Strategy replay after trading costs</h3><button id="runStrategy">${m.strategyLoading?'Running…':'Run 1h strategy test'}</button></div><p class="detailNote">500 available 1h candles, closed-bar signals, next-bar-open entries, no overlapping trades, 48h maximum hold. If stop and target touch in one bar, stop is assumed first. Separate from forecast accuracy; no real orders are placed.</p>${r?`<p><b>${r.count} trades · ${r.count?(r.wins/r.count*100).toFixed(1)+'% net winners':'Insufficient trade sample'}</b></p><p>Gross mean ${r.grossMean==null?'—':pct(r.grossMean)} · net mean ${r.netMean==null?'—':pct(r.netMean)} · compounded net ${pct(r.netReturn)} · maximum drawdown ${r.maxDrawdown.toFixed(2)}%</p><p class="detailNote">Assumed fee ${r.costs.feeBps} bps/side; slippage ${r.costs.slippageBps} bps/side; funding ${r.costs.fundingBps} bps/8h (estimated, not actual settlement history). ${r.count<30?'Small sample; do not infer a reliable win rate.':''}</p><details><summary>Trade-by-trade replay (${r.trades.length})</summary><div class="comparisonWrap"><table class="comparisonTable"><thead><tr><th>Direction / entry UTC</th><th>Exit reason</th><th>Gross</th><th>Net</th></tr></thead><tbody>${r.trades.map(t=>`<tr><td>${t.direction} · ${new Date(t.entryTime).toISOString().slice(0,16)}</td><td>${esc(t.reason)}</td><td>${pct(t.gross)}</td><td>${pct(t.net)}</td></tr>`).join('')}</tbody></table></div></details>`:`<p>${esc(m.strategyError??'Run a replay to inspect whether the displayed rules remain profitable after assumed costs.')}</p>`}<p class="detailNote">${demo?'Synthetic demo results; not market performance.':'Historical replay is not prospective validation.'} Manage cost assumptions in Account.</p></section>`;}
async function runStrategy(m){if(m.strategyLoading)return;m.strategyLoading=true;m.strategyError=null;renderDetail();const gen=generation;try{let candles;if(demo){const source=demoCandles(ASSETS.some(x=>x[0]===m.symbol)?m.symbol:'BTC','15m'),end=Math.floor(Date.now()/3600000)*3600000;candles=source.map((c,i)=>({...c,t:end-(source.length-i)*3600000,closed:true}));}else candles=parseBybit(await api(`kline?category=linear&symbol=${m.symbol}USDT&interval=60&limit=500`),60);if(gen!==generation)return;m.strategy=replayStrategy(candles,account.prefs.costs);}catch(e){m.strategyError='Replay unavailable: '+e.message;}finally{m.strategyLoading=false;if(gen===generation&&selected===m.symbol&&$('#detail').open)renderDetail();}}
window.addEventListener('account-change',()=>{saved=new Set(account.prefs.watchlist);render();if($('#detail').open)renderDetail();});account.init();

async function loadChecks(m,force=false){if(m.checksLoading||m.timeframes&&!force)return;const gen=generation;m.checksLoading=true;m.timeframes={};await Promise.all([['15m',15],['1h',60],['4h',240],['1D',1440]].map(async([label,minutes])=>{try{if(demo){m.timeframes[label]={error:'Synthetic demo has no independent live timeframe history'};return;}const rows=await api(`kline?category=linear&symbol=${m.symbol}USDT&interval=${minutes===1440?'D':minutes}&limit=200`);if(gen===generation)m.timeframes[label]=timeframeEvidence(rows,minutes);}catch(e){if(gen===generation)m.timeframes[label]={error:e.message};}}));m.checksLoading=false;if(gen===generation&&selected===m.symbol&&$('#detail').open)renderDetail();}
